// Правила игр для окна «📖 Правила» (js/games/gamekit.js). СОБРАНО: node scripts/make-rules.mjs из api/_lib/games-seo.js —
// правишь правила, правь там и пересобери (руками этот файл не менять).
window.GAME_RULES = {"2048":{"rt":"Как играть","rules":["Поле 4×4. Каждым ходом все плитки сдвигаются в выбранную сторону до упора.","Две одинаковые плитки, столкнувшись, складываются в одну: 2 + 2 = 4, 4 + 4 = 8 и так далее.","За каждое сложение начисляются очки — столько, сколько получилось на новой плитке.","После каждого хода на свободной клетке появляется новая плитка 2 или 4.","Цель — собрать плитку 2048. Игра кончается, когда ходов больше нет."],"tt":"Советы","tips":["Выбери угол и держи самую большую плитку в нём — не двигай её оттуда без крайней нужды.","Пользуйся в основном двумя-тремя направлениями, а четвёртое — только если деваться некуда.","Заполняй ряд у «своего» угла по убыванию: 1024, 512, 256… — так сложения идут цепочкой."]},
"podzem":{"rt":"Как играть","rules":["Создай персонажа и мир (зерно можно не вводить). Ходи A/D, прыгай пробелом, копай и ставь левой кнопкой мыши там, где курсор.","Наруби дерева топором и в 🎒 «Вещи» сделай верстак — рядом с ним делаются платформы, двери, стены и сундуки.","До ночи построй дом: стены сзади, дверь, факел (дерево + гель от слизней). Ночью выходят зомби.","Копай вниз: руду плавь в печи (камень, дерево, факелы) в слитки, на наковальне куй кирки и мечи получше.","Кристаллы жизни ❤ в пещерах прибавляют здоровье. Желейная приманка и Совиный манок зовут боссов."],"tt":"Советы","tips":["Глубинит берёт только золотая кирка, жарит у лавы — глубинная. Сначала прокачай кирку.","Возвратный амулет переносит домой — без него из глубины выбираться долго.","Молоток делает из блока полублок и склоны — по ним удобно ходить, а ещё молотком снимают стены.","На телефоне: держи палец на клетке — копать или ставить там, короткое нажатие — открыть дверь или сундук. Для точной стройки — 🎯 «режим строителя».","Ctrl — умный курсор: кирка сама берёт ближайший блок к курсору, блок встаёт туда, где держится. Shift — держи, и игра подаст нужный инструмент.","Крюк-кошка (наковальня: 3 железных слитка и 10 верёвок) — клавиша E: цепляйся за потолок и стены пещер.","Зерно мира можно отправить другу: введи его в «Новый мир» — получится такой же мир."]},
"kletochki":{"rt":"Как играть","rules":["Плыви туда, где мышь (на телефоне — веди пальцем где угодно). Чем больше клетка, тем она медленнее.","Ешь цветные точки и клетки, которые меньше тебя хотя бы на четверть: накрой их почти целиком.","Пробел или ✂️ — разделиться: половинка вылетает вперёд и может догнать добычу. Через 10–35 секунд части снова слипаются.","W или 💧 — выбросить немного массы: так можно покормить друга или колючку (7 выбросов — колючка «стреляет» новой).","Колючки опасны большим клеткам (масса от 133): наплывёшь — лопнешь на кусочки. Маленькие проплывают под ними.","Съели — нажми «Ещё раз». Раунд длится 5 минут: побеждает тот, у кого в конце больше масса.","«🧬 Путь клетки»: ешь сахар и клетки — получаешь ДНК 🧬. В «Эволюции» покупай части и ставь их на мембрану, с «Липкостью» клетки после деления держатся вместе (колония). Вехи открывают Риф и Глубину, а в конце — «🌱 На сушу»."],"tt":"Советы","tips":["В начале не спеши: ешь точки и держись подальше от больших клеток.","Делиться выгодно, когда добыча рядом и вдвое меньше половинки, — иначе тебя самого разберут по кусочкам.","Маленькой клетке колючка — укрытие: большие за ней не погонятся.","Большая клетка медленно худеет — не стой на месте, ищи новую еду.","Загляни в таблицу лидеров: самого большого лучше обходить стороной."]},
"chervyachki":{"rt":"Как играть","rules":["Червячок ползёт туда, куда показывает мышь (на телефоне — веди пальцем где угодно, это джойстик).","Ешь светящиеся огоньки — растёшь в длину и толщину. Длинный червячок поворачивает медленнее.","Держи кнопку мыши, пробел или ⚡ — ускорение: вдвое быстрее, но длина тратится, а позади падают огоньки.","Врезался головой в чужого червячка — рассыпаешься на огоньки. В себя врезаться нельзя — свой хвост не страшен.","Голова в голову — уступает тот, кто короче. Край арены не убивает: червячок скользит вдоль него.","Первые 2 секунды после появления ты «призрак»: проходишь сквозь всех. Раунд — 5 минут: побеждает самый длинный."],"tt":"Советы","tips":["Не лезь в гущу больших червячков в начале — собирай огоньки по краям.","Подрезай: выскочи перед головой соперника — он врежется в тебя и рассыплется.","Ускоряйся коротко: чтобы убежать или успеть к огонькам от чужого червячка.","Большой червячок может окружить маленького кольцом — не заезжай внутрь.","После «рассыпался» поблизости много еды — но и много желающих её съесть."]},
"studio3d":{"rt":"Как сделать свой мир","rules":["Открой «Студию 3D» и выбери шаблон: площадка, обби, остров, лагерь у костра или зимний лес.","«➕ Деталь» — добавь блок и потяни цветные стрелки: двигай, меняй размер, крути.","Справа выбери цвет и материал, во вкладке «⛰ Земля» нарисуй холмы, в «☀ Свет» — время суток.","«📜 Скрипт» → «📚 Примеры»: монетка, лава, дверь, платформа — вставь и нажми «▶ Играть»."],"tt":"Подсказки","tips":["Зажми правую кнопку мыши и води мышью, чтобы осмотреться; WASD — лететь, колесо — ближе и дальше.","Ctrl+D — копия выбранного, Ctrl+Z — отменить, Ctrl+G — собрать детали в модель.","Сетка 1 и угол 15° помогают ставить детали ровно; «Сетка: нет» — для точной подгонки.","Свою модель перетащи прямо в окно студии — файл .glb из Blender или Sketchfab."]},
"world":{"rt":"Как играть","rules":["WASD — идти, Shift — бег, Пробел — прыжок, мышь — камера; на телефоне — джойстик и кнопки.","E — действие: сесть, открыть дверь, вызвать лифт, сесть в машину. M — карта мира и телепорты.","В машине: W/S — газ и назад, A/D — руль, Пробел — тормоз, Shift — ускорение, H — сигнал, E — выйти.","В вертолёте: Пробел — вверх, C — вниз, W/S — вперёд и назад. В самолёте: W — газ, на скорости Пробел — взлёт.","В городах выбери работу в мэрии — за задания платят игровые деньги и немного монет 🪙."],"tt":"Советы","tips":["Городской вертолёт стоит на крыше небоскрёба «Сити-1» — поднимись туда на лифте.","На катере можно проплыть под мостами по каналу Большого города.","Большой город — 16+, Боевая зона — 12+: возраст спрашивается один раз и виден только тебе.","Позови друга в мир — и садитесь в одну машину: водитель и пассажиры видят друг друга."]},
"kubomir":{"rt":"Как играть","rules":["Нажми «➕ Новый мир», выбери «Выживание» или «Творчество» и сложность. Зерно — одинаковое слово даёт всем один и тот же мир.","На компьютере: WASD — ходить, мышь — смотреть, левая кнопка — ломать, правая — поставить или открыть, Tab — вещи, 1–9 — выбор.","На телефоне: джойстик слева, палец справа — смотреть, кнопки ⛏ — ломать, 🧱 — поставить, 🎒 — вещи.","Сначала бревно → доски → верстак → палки → деревянная кирка. Камень → каменная кирка и печь. Уголь → факелы.","Ночью опасно: построй укрытие и освети его факелами. Ешь, когда голодно, — иначе не восстанавливается здоровье."],"tt":"Советы","tips":["Железо копай каменной киркой, золото и алмазы — железной, обсидиан — только алмазной.","Алмазы лежат глубоко — ниже 16-го уровня, часто рядом с лавой. Где вода встречается с лавой, получается обсидиан или булыжник.","Факел на стене пещеры — и монстры там не появятся, а ты найдёшь дорогу назад.","Песок и гравий падают — не копай их прямо над собой.","Сундук и печь открываются правой кнопкой; Shift + нажатие перекидывает всю стопку."]},
"unity":{"rt":"Как выложить свою игру из Unity","rules":["Открой «Unity-игры» → «📘 Как сделать игру» и нажми «📦 Скачать SDK (zip)» — архив с SDK для Unity.","Добавь SDK в проект Unity и в меню «SDK Денчика» выбери «Настроить сборку для сайта» — шаблон и сжатие настроятся сами.","Собери игру под WebGL и выложи папку сборки на GitHub Pages или itch.io.","«➕ Добавить свою игру из Unity» → вставь ссылку на index.html сборки, нажми «▶ Проверить» и сохрани — по ссылке или в каталог."],"tt":"Подсказки","tips":["D37.Init — первым делом: игра узнает ник игрока и вошёл ли он в аккаунт.","D37.AddCoins — монеты за раунд, D37.Over(очки, победа) в конце раунда — рекорд и монеты засчитает сервер сайта.","Для игры с друзьями — D37.Room.Create(): ссылку на комнату сайт покажет сам.","В редакторе Unity игра работает без сайта: D37.Simulate добавит ненастоящих игроков для проверки."]},
"krokodil":{"rt":"Как играть","rules":["Создай комнату и отправь ссылку друзьям. Когда все зашли, ведущий нажимает «Начать игру».","Художник выбирает одно из трёх слов и рисует его. Писать буквы и цифры на рисунке нельзя — только рисовать!","Остальные пишут догадки в чат. Угадал — получаешь очки: чем раньше, тем больше, первому — бонус.","Со временем открываются буквы-подсказки. Ход заканчивается, когда все угадали или вышло время.","Рисуют все по очереди. После последнего раунда — итоги и пьедестал."],"tt":"Советы","tips":["Художнику: сначала нарисуй главное крупно, детали — потом. Заливка 🪣 экономит время.","Угадывающим: пиши всё, что приходит в голову, — за неверные догадки очки не снимают.","«🔥 Близко!» значит, что ты почти угадал: попробуй другое окончание или похожее слово.","Для стрима: включи «Свои слова» и загадай то, что знают твои зрители."]},
"balda":{"rt":"Как играть","rules":["В середине поля 5×5 стоит слово из 5 букв. Игроки ходят по очереди.","Ход: поставь одну букву в пустую клетку рядом с буквами (по стороне, не по диагонали).","Составь слово, проводя по соседним клеткам — вверх, вниз, влево, вправо. Каждая клетка — один раз, и слово обязательно проходит через новую букву.","Слова — существительные в начальной форме («кот», «ножницы»), каждое — один раз за игру.","За слово — столько очков, сколько в нём букв. Нет слова — пропусти ход.","Поле заполнилось или 4 пропуска подряд — побеждает тот, у кого больше очков."],"tt":"Советы","tips":["Ставь буквы так, чтобы самому составить длинное слово, а сопернику оставить мало вариантов.","Ищи слова «змейкой»: путь может поворачивать сколько угодно раз.","Короткие слова на 2–3 буквы — ёж, уж, оса, кит — выручают, когда длинных не видно.","Окончания -ка, -ок, -ик помогают растянуть слово: кот → котик."]},
"fillword":{"rt":"Как играть","rules":["Все буквы поля — это спрятанные слова, свободных клеток нет.","Слово составляется из соседних букв: вверх, вниз, влево или вправо (не по диагонали). Путь может поворачивать сколько угодно раз.","Каждая буква входит ровно в одно слово, поэтому найденные слова «выключают» свои клетки.","Проведи по буквам слова (или нажми их по очереди) — если это слово из загадки, оно закрасится.","Под полем видно, сколько слов осталось и сколько в каждом букв. Нашёл все — уровень пройден.","Подсказка 💡 показывает первую букву одного слова, но снижает очки. Очки — за размер поля и скорость."],"tt":"Советы","tips":["Начинай с углов: у угловой буквы всего два соседа, и слово через неё легко угадать.","Смотри на список длин: если осталось одно слово из 3 букв, ищи маленький «островок» из трёх клеток.","Буквы Ь, Ъ и Ы никогда не стоят в начале слова — значит, слово через них начинается где-то рядом.","Каждое найденное слово сужает поле — оставшиеся буквы часто складываются сами."]},
"sudoku":{"rt":"Как играть","rules":["Поле 9×9 разбито на 9 квадратов 3×3. Часть цифр уже стоит.","В каждой строке, каждом столбце и каждом квадрате 3×3 цифры от 1 до 9 должны встречаться ровно по одному разу.","Выбери клетку и нажми цифру. Неверная цифра считается ошибкой — после трёх ошибок игра окончена.","Не уверен — включи «Заметки» ✏️ и запиши варианты маленькими цифрами."],"tt":"Советы","tips":["Ищи строки, столбцы и квадраты, где не хватает одной-двух цифр.","Для каждой цифры проверяй, в какие клетки квадрата она может встать: если только в одну — ставь.","Записывай варианты заметками: когда в клетке остаётся один вариант — это ответ.","На сложных уровнях ищи «пары»: две клетки с одинаковыми двумя вариантами исключают эти цифры из соседей."]},
"mahjong":{"rt":"Как играть","rules":["Нажми на картинку, потом на такую же. Если их можно соединить линией не больше чем с двумя поворотами, пара исчезнет.","Линия идёт только по пустым клеткам и может выходить за край поля.","Убери все пары до конца времени — и уровень пройден.","На каждом уровне 3 подсказки и 2 перемешивания. Время кончилось — можно один раз добавить минуту."],"tt":"Советы","tips":["Начинай с краёв поля: картинки там соединяются легче всего.","Ищи пары, которые стоят рядом или на одной линии, — это быстрые очки и комбо.","На уровнях с падением смотри, куда сдвинутся картинки, прежде чем убирать пару.","Не трать подсказки в начале уровня — они нужнее, когда картинок мало."]},
"miner":{"rt":"Как играть","rules":["Цифра в открытой клетке — сколько мин в восьми клетках вокруг неё.","Нажми на клетку, чтобы открыть её. Если там мина — игра окончена.","Правый клик (на телефоне — долгое нажатие) ставит флажок туда, где ты уверен, что мина.","Победа — когда открыты все клетки без мин. Чем быстрее, тем больше очков."],"tt":"Советы","tips":["Начинай с углов открытой области: там цифры подсказывают больше всего.","Цифра 1 рядом с одной закрытой клеткой — значит, мина именно там.","Если вокруг цифры уже стоят все её флажки, остальные соседи безопасны — открывай их «аккордом».","Иногда без угадывания не обойтись: выбирай клетку, где мина менее вероятна."]},
"freecell":{"rt":"Как играть","rules":["Все карты разложены открытыми в 8 рядов. Цель — собрать в доме 4 масти от туза до короля.","В рядах карты кладутся по убыванию с чередованием цвета: на чёрную восьмёрку — красную семёрку.","В каждую из 4 свободных ячеек можно положить одну любую карту. На пустое место в ряду — любую карту.","Перенести сразу несколько карт можно, если хватает свободных ячеек и пустых рядов: (ячейки + 1) × 2 за каждый пустой ряд."],"tt":"Советы","tips":["Не забивай все ячейки сразу — без них не перенести даже две карты.","Пустой ряд ценнее свободной ячейки: он удваивает число карт, которые можно перенести.","Раньше всего освобождай тузы и двойки — они уходят в дом сами.","Почти все раздачи решаются. Застрял — отмени ходы и попробуй другой путь."]},
"kosynka":{"rt":"Как играть","rules":["Цель — разложить все 52 карты по четырём стопкам «дома»: каждая масть по порядку от туза до короля.","В рядах карты кладутся по убыванию с чередованием цвета: на чёрную десятку — красную девятку.","На пустое место в ряду можно положить только короля (или цепочку, которая с него начинается).","Нет ходов — бери карты из колоды (по одной или по три). Колода кончилась — переверни её и пройди ещё раз."],"tt":"Советы","tips":["Первым делом открывай закрытые карты в длинных рядах.","Не спеши класть карты в дом: иногда они нужны в рядах, чтобы переложить карты другого цвета.","Освобождай ряд, только когда есть король, которого туда можно положить.","Запутался — отмени несколько ходов и попробуй по-другому."]},
"pauk":{"rt":"Как играть","rules":["На карту можно положить карту на единицу младше любой масти: на девятку — восьмёрку.","Переносить несколько карт разом можно, только если они одной масти и идут подряд по убыванию.","Цепочка одной масти от короля до туза уходит с поля. Собери 8 таких — пасьянс сошёлся.","Нет ходов — раздай карты из колоды: по одной в каждый ряд (все ряды должны быть заняты)."],"tt":"Советы","tips":["Открывай закрытые карты в первую очередь.","Клади карты на карты своей масти — такие цепочки потом можно переносить целиком.","Пустой ряд — самое ценное: используй его, чтобы разобрать длинные разномастные цепочки.","Перед раздачей из колоды наведи порядок: новые карты закроют все ряды."]},
"blocks":{"rt":"Как играть","rules":["Перетащи фигуру из нижнего ряда на поле. Можно и по-другому: нажми на фигуру, потом на клетку. Поворачивать фигуры нельзя.","Заполни целиком строку или столбец — линия исчезнет. Каждая клетка фигуры даёт 1 очко, линия — 80, две разом — 240, три — 480.","Собираешь линии хотя бы раз за три хода подряд — растёт комбо и множитель очков (до ×5). Очистил всё поле — ещё +300.","Поставил все три фигуры — появятся новые. Если ни одна не помещается, игра окончена; один раз за игру можно взять новые фигуры."],"tt":"Советы","tips":["Держи свободное место под большие фигуры: квадрат 3×3 и палку из 5 клеток.","Ставь фигуры вплотную к краям и друг к другу — одиночные дырки потом трудно закрыть.","Прежде чем ставить первую фигуру, посмотри на все три: найди место для каждой.","Старайся собирать по две-три линии разом и не прерывать комбо."]},
"domino":{"rt":"Как играть","rules":["Каждому раздают по 7 костяшек, остальные — «базар».","Первым ходит тот, у кого дубль 1–1 (если ни у кого нет — 2–2, 3–3 и так далее).","Ход — приставь к любому концу цепочки костяшку с тем же числом точек. Дубли кладут поперёк.","Нечем ходить — бери из базара по одной, пока не найдёшь подходящую. Базар пуст — пропусти ход.","Выложил все костяшки — раунд твой: получаешь сумму точек из рук соперников.","«Рыба» — никто не может сходить: раунд выигрывает тот, у кого в руке меньше очков.","Игра идёт до 51 или 101 очка. У кого меньше всех очков в конце — «козёл»."],"tt":"Советы","tips":["Сбрасывай тяжёлые костяшки и дубли пораньше — в конце раунда они дорого стоят.","Оставляй на концах те числа, которых у тебя много, — тогда тебе всегда будет чем ходить.","Следи, на каких числах соперник брал из базара: у него их нет — закрывай концы этими числами."]},
"chess":{"rt":"Как играть","rules":["Белые ходят первыми. Нажми на фигуру — подсветятся клетки, куда она может пойти, потом нажми на клетку.","Рокировка — ход королём на две клетки к ладье (если король и ладья не ходили, а поля не под боем).","Пешка, дошедшая до последней горизонтали, превращается в ферзя, ладью, слона или коня — на выбор.","Мат — королю шах, и спастись нельзя: победа. Пат — ходить некуда, но шаха нет: ничья."],"tt":"Советы","tips":["В начале партии занимай центр пешками и выводи коней и слонов.","Сделай рокировку пораньше — король в углу в безопасности.","Перед каждым ходом проверь: не оставляешь ли фигуру под боем."]},
"arena":{"rt":"Как играть","rules":["Левый палец — бег (джойстик появляется там, где коснулся). На компьютере — WASD или стрелки.","Правый палец — прицел: потяни и отпусти — выстрел. Короткий тап — выстрел в ближайшего соперника. На компьютере — мышь и клик.","У тебя 3 заряда, они восстанавливаются сами. Попадания заряжают «супер» (кнопка ⚡ или пробел).","В кустах тебя не видно, пока не выстрелишь или пока соперник не подойдёт вплотную. ❤️ — аптечка.","Первым набрал 5 побед — выиграл. За 2,5 минуты не набрали — побеждает тот, у кого больше."],"tt":"Советы","tips":["Не стреляй все три заряда сразу — оставь один на добивание.","Стреляй с упреждением: туда, куда соперник бежит.","Сидишь в кустах — жди, пока соперник подойдёт, и бей «супером» в упор."]},
"nardy":{"rt":"Как играть","rules":["У каждого 15 шашек на «голове». Ходите по кругу в одну сторону, начиная с противоположных углов.","Бросаешь два кубика: каждый — ход одной шашкой на столько точек. Дубль — четыре хода.","Вставать на точку, где стоит чужая шашка, нельзя. С головы за ход — одна шашка (на первом ходу при 6-6, 4-4 и 3-3 — две).","Нельзя строить заборчик из 6 шашек подряд, если впереди него нет ни одной шашки соперника.","Кубики нужно использовать по максимуму; если можно сыграть только один — играешь больший.","Когда все 15 шашек дома, их можно выбрасывать. Выбросил все первым — победа; соперник не выбросил ни одной — марс."],"tt":"Советы","tips":["Не спеши снимать шашки с головы — но и не держи их там до конца: потом может не хватить ходов.","Занимай точки на пути соперника: шесть подряд нельзя, а пять — можно, это сильная преграда.","Дубли в начале — шанс быстро вывести шашки с головы."]},
"ludo":{"rt":"Как играть","rules":["У каждого 4 фишки в домике. Чтобы вывести фишку на старт, нужно выбросить 6.","Фишка идёт по кругу на столько клеток, сколько выпало, потом — по своей цветной дорожке к финишу.","Встал на клетку с чужой фишкой — она возвращается в домик. На клетках ★ и стартовых сбивать нельзя.","Шестёрка, сбитая фишка или фишка на финише — бросок ещё раз. Три шестёрки подряд — ход сгорает.","До финиша нужно выбросить точное число. Кто первым привёл все 4 фишки, тот победил."],"tt":"Советы","tips":["Не держи все фишки в домике: на шестёрку выводи новую, чтобы было из чего выбирать.","Становись на звёздочки, когда соперник близко сзади, — там тебя не собьют.","Если можешь сбить чужую фишку — почти всегда сбивай: это ещё и лишний бросок."]},
"pool":{"rt":"Как играть","rules":["Разбой: поставь белый биток в левой четверти стола и разбей пирамиду.","Первый забитый после разбоя шар определяет твою группу: сплошные (1–7) или полосатые (9–15).","Забил свой шар — бьёшь ещё. Не забил — ход переходит к сопернику.","Фол — биток в лузе, промах или первым задет чужой шар. После фола соперник ставит биток куда хочет.","Когда свои шары кончились — забей чёрный 8. Забил его раньше или с фолом — проигрыш."],"tt":"Советы","tips":["Целься так, чтобы белый кружок на конце линии касался прицельного шара со стороны, противоположной лузе.","Не бей всегда в полную силу: мягкий удар точнее и оставляет биток в удобном месте.","Шар в руке — ставь биток прямо напротив шара и лузы."]},
"durak":{"rt":"Как играть","rules":["Каждому раздают по 6 карт. Открытая карта под колодой задаёт козырь.","Первым ходит тот, у кого младший козырь. Ход — положить любую карту.","Отбиться — положить старшую карту той же масти или любой козырь. На козырь — только старший козырь.","Остальные могут подкидывать карты того же достоинства, что уже на столе, — не больше 6 за раунд.","Не можешь отбиться — «Беру»: забираешь все карты со стола. Отбился — «Бито», и ты ходишь следующим.","После раунда все добирают из колоды до 6. Кто последним остался с картами — дурак."],"tt":"Советы","tips":["Не трать козыри в начале — они решают концовку, когда колода закончится.","Ходи с мелких карт и с пар: соперникам сложнее отбиваться.","Запоминай вышедшие карты — к концу игры станет понятно, что у соперников."]},
"uno":{"rt":"Как играть","rules":["Каждому раздают по 7 карт. Ходи картой того же цвета или того же значения, что лежит сверху.","Дикая карта ★ подходит ко всему — после неё выбираешь цвет. Дикая +4 — следующий ещё и берёт 4 карты.","⊘ — следующий пропускает ход, ⇄ — круг идёт в обратную сторону, +2 — следующий берёт две и пропускает.","Нечем ходить — возьми карту из колоды. Подошла — можно сразу сыграть.","Осталась одна карта — нажми «Одна!». Не успел — соперник нажмёт «Поймал!», и ты возьмёшь 2.","Кто первым сбросит все карты, побеждает и получает очки за карты соперников."],"tt":"Советы","tips":["Придерживай дикие карты до конца — ими можно сменить цвет в нужный момент.","Если у следующего игрока мало карт — бей его «+2», «+4» и «пропуском».","Нажимай «Одна!» заранее, когда остаётся две карты и ты ходишь, — так не забудешь."]},
"td":{"rt":"Как играть","rules":["Выбери карту и нажми «Играть». Нажми на свободную клетку — выбери башню.","Нажми на башню, чтобы улучшить её (до 3-го уровня) или продать.","Монстр, дошедший до замка, отнимает жизнь (огры — 2, боссы — 5 и 10). Жизней — 20.","Пройди все 20 волн. Кнопка «▶ Волна» запускает следующую раньше — за это дают золото."],"tt":"Советы","tips":["Ставь башни у поворотов дороги — там монстры дольше в радиусе.","Мороз рядом с пушкой — сильная связка: замедленная толпа получает весь урон по площади.","К 10-й волне держи хотя бы одну ⚡ Молнию или 🎯 Снайпера: у босса броня.","В битве не трать всё на отправку монстров: сначала крепкая защита, потом атака."]},
"raid":{"rt":"Как играть","rules":["Основай военную базу в Боевой зоне «Мира Денчика» (12+) или вступи в базу друга по ссылке. Постройте казарму и тренируйте отряды — они учатся по времени, даже когда никого нет.","Нажми «⚔️ В бой!» — сервер подберёт базу по штабу и кубкам. 30 секунд разведки, потом 3 минуты боя. Армию ведут главарь и офицеры (главарь может разрешить всем).","Выбери отряд внизу и нажми на зелёную полосу у края базы — отряд высадится. Можно вести пальцем — высадится строй.","Звёзды: одна — за половину построек, одна — за штаб, одна — за всё. Победа приносит кирпичи в казну и кубки базе, поражение отнимает кубки.","После сильного набега на базу ставится щит. Нападение на другую базу снимает ваш щит."],"tt":"Советы","tips":["Силач идёт прямо к обороне — пускай его первым, а бойцов и лучников следом.","Подрывник взрывает стены: высаживай его рядом со стеной, за которой штаб.","Лучники стреляют из-за стен — ставь их за спиной Силача.","Собирайте кирпичи из карьеров и завода вовремя: в набеге забирают часть того, что в них копится.","Ставьте пушки и вышки так, чтобы они прикрывали друг друга, а штаб — в середину за стену."]},
"horde":{"rt":"Как играть","rules":["Выбери героя и нажми «Играть». Ходи стрелками / WASD или зажми палец в любом месте поля и веди.","Оружие стреляет само. Собирай кристаллы опыта — за новый уровень выбери одно из трёх улучшений.","Оружие 5-го уровня + «своя» пассивка = эволюция ⭐ (подсказка — на карточке улучшения).","Продержись 10 минут. Погиб — можно один раз возродиться."],"tt":"Советы","tips":["Не стой на месте: двигайся по кругу и собирай опыт по краю толпы.","В начале бери 3–4 оружия, потом качай их до 5-го уровня ради эволюций.","Курочка 🍗 лечит, магнит 🧲 притягивает весь опыт, бомба 💣 очищает экран.","Сундук с демона почти всегда даёт эволюцию — не пропускай его."]},
"words":{"rt":"Как играть","rules":["Загадано существительное из пяти букв в именительном падеже, единственном числе.","Введи любое слово из пяти букв, которое есть в словаре, и нажми «Ввод».","Зелёная клетка — буква есть в слове и стоит на этом месте.","Жёлтая клетка — буква есть в слове, но в другом месте.","Серая клетка — такой буквы в слове нет.","На всё — шесть попыток. Буквы Е и Ё считаются одной буквой."],"tt":"Советы","tips":["Начинай со слова с частыми буквами и разными гласными: например, «ОКЕАН» или «ПИРОГ».","Не повторяй серые буквы — они точно не помогут.","Жёлтую букву переставляй на другое место: так быстрее найдёшь, где она стоит.","Помни, что буквы в слове могут повторяться."]},
"cities":{"rt":"Как играть","rules":["Первый игрок называет любой город.","Следующий называет город, который начинается на последнюю букву предыдущего: Москва → Архангельск → Калуга → Анапа…","Если город кончается на Ь, Ъ, Ы или Й, берётся предпоследняя буква: Тверь → Рязань → Новосибирск.","Повторять города нельзя — каждый город в партии называется один раз.","Буквы Е и Ё считаются одной буквой, дефисы и пробелы можно не писать: «ростов на дону» засчитается.","Кто не смог назвать город за отведённое время или сдался — проиграл."],"tt":"Советы","tips":["Держи в голове города на «неудобные» буквы: на А (Абакан, Азов, Ачинск), на К (Кострома, Калининград) и на Р (Рыбинск, Ржев).","Старайся отвечать городом, который кончается на редкую букву — бот на «Сложном» делает то же самое с тобой.","Играешь по всему миру — вспоминай столицы: почти на любую букву найдётся столица."]},
"checkers":{"rt":"Как играть","rules":["Играют на тёмных клетках доски 8×8, у каждого по 12 шашек. Белые ходят первыми.","Простая шашка ходит на одну клетку вперёд по диагонали.","Бить обязательно. Простая шашка бьёт и вперёд, и назад, перепрыгивая шашку соперника на свободную клетку за ней.","Если после взятия можно бить дальше — бьют до конца серии.","Шашка, дошедшая до последнего ряда, становится дамкой. Если это случилось посреди серии — она продолжает бить уже как дамка.","Дамка ходит и бьёт по диагонали на любое расстояние.","«Турецкий удар»: сбитые шашки снимаются только после хода, и одну шашку дважды за серию бить нельзя.","Проигрывает тот, у кого не осталось шашек или ходов."],"tt":"Советы","tips":["Не спеши выводить крайние шашки: шашка у края защищена с одной стороны, но и сама мало на что влияет.","Держи центр доски — оттуда легче атаковать и сложнее попасть под размен.","Помни про обязательное взятие: им можно заманить соперника в серию, которая выгодна тебе."]},
"sea":{"rt":"Как играть","rules":["Поле 10×10, столбцы обозначены буквами от А до К, строки — цифрами от 1 до 10.","У каждого флот из 10 кораблей: один четырёхпалубный, два трёхпалубных, три двухпалубных и четыре однопалубных.","Корабли не касаются друг друга — ни сторонами, ни углами.","Игроки стреляют по очереди, выбирая клетку на поле соперника.","Попал — стреляешь ещё раз. Промахнулся — ход переходит к сопернику.","Когда все клетки корабля подбиты, он потоплен, а клетки вокруг него отмечаются как пустые.","Побеждает тот, кто первым потопит весь флот соперника."],"tt":"Советы","tips":["Сначала стреляй «через клетку», как по шахматной доске, — так быстрее найдёшь большие корабли.","Ранил корабль — бей по соседним клеткам, а когда поймёшь направление, иди вдоль линии.","Однопалубные корабли обычно остаются напоследок: оставь на них выстрелы по пустым углам."]},
"snake":{"rt":"Как играть","rules":["Змейка всё время ползёт вперёд — ты только поворачиваешь её.","Съел яблоко — змейка становится на клетку длиннее, а на поле появляется новое яблоко.","Врезался в стену или в свой хвост — игра окончена.","Счёт — число съеденных яблок. 25 и больше засчитываются как победа."],"tt":"Советы","tips":["Двигайся вдоль краёв поля и «змейкой» по рядам — так хвост не запрёт тебя в угол.","Не гонись за яблоком напрямую, если для этого придётся развернуться рядом с хвостом.","Нажимай повороты заранее: игра запоминает до трёх нажатий подряд."]},
"memory":{"rt":"Как играть","rules":["Все карточки лежат рубашкой вверх.","За ход открываешь две карточки. Если картинки одинаковые — пара остаётся открытой.","Если разные — карточки закрываются, и нужно запомнить, что где лежало.","Игра кончается, когда найдены все 10 пар. Очки: 1000 минус 25 за каждый ход сверх десяти и минус 2 за каждую секунду."],"tt":"Советы","tips":["Открывай карточки по порядку, ряд за рядом, — так проще запоминать их положение.","Проговаривай про себя: «пицца — второй ряд слева». Так память работает лучше.","Уложиться в 20 ходов — это уже победа."]},
"ttt":{"rt":"Как играть","rules":["Поле 3×3. Игроки по очереди ставят свой знак — крестик или нолик — в свободную клетку.","Первым ходит крестик.","Побеждает тот, кто первым выстроит три своих знака в ряд: по горизонтали, вертикали или диагонали.","Если все клетки заняты, а ряда нет — ничья."],"tt":"Советы","tips":["Играешь крестиками — начни с центра или угла: так больше шансов поставить «вилку».","«Вилка» — ход, после которого у тебя сразу две угрозы выиграть. Закрыть обе соперник не успеет.","Против «Непобедимого» выиграть нельзя: при правильной игре крестики-нолики всегда заканчиваются ничьей. Ничья с ним уже считается успехом."]},
"emoji":{"rt":"Как играть","rules":["Нажми «Начать» — появятся четыре эмодзи и четыре варианта игры.","Выбери игру, которую зашифровали эмодзи. На ответ — 10 секунд.","Верный ответ — 100 очков плюс до 50 за скорость; каждый следующий верный подряд добавляет бонус.","После 10 раундов — итог, рекорд и кнопка «Поделиться»."],"tt":"Советы","tips":["Сначала ищи самый «говорящий» эмодзи: 🍕 и 🐻 — почти всегда FNAF, ⛏️ и 🧱 — Майнкрафт.","Не трать время на сомнения: за скорость дают до половины очков раунда.","Играй с другом: у вас одинаковые загадки, побеждает тот, кто быстрее и точнее."]},
"reaction":{"rt":"Как играть","rules":["Нажми, чтобы начать, и жди: экран станет зелёным через случайное время.","Как только увидел зелёный — жми как можно быстрее.","Нажал раньше — фальстарт, попытка начнётся заново.","После 5 попыток считается средняя реакция. Очки = 1000 − среднее время в мс: чем быстрее, тем больше очков."],"tt":"Советы","tips":["Средняя реакция взрослого человека на зрительный сигнал — примерно 250 мс. Меньше 200 мс — отличный результат.","Смотри в центр экрана, а палец держи прямо над кнопкой или клавишей.","Высыпаешься и не устал — результат заметно лучше. Попробуй утром и вечером и сравни."]},
"catch":{"rt":"Как играть","rules":["Двигай платформу влево-вправо и лови падающие предметы.","💰 даёт 10 очков, 💎 — 50 очков, ❤️ возвращает потерянную жизнь.","🚫 бан и 💣 бомба отнимают жизнь. Кончились жизни — игра окончена.","Чем дольше играешь, тем быстрее всё падает."],"tt":"Советы","tips":["Не гонись за каждым донатом: одна пропущенная монета лучше, чем пойманная бомба.","Алмаз стоит пять донатов — ради него можно рискнуть.","На телефоне удобнее тянуть пальцем, на компьютере — мышью."]},
"guess":{"rt":"Как играть","rules":["В каждом раунде показывается увеличенный фрагмент превью ролика.","За 12 секунд картинка отдаляется до целого кадра.","Выбери одно из четырёх названий. Правильный ответ даёт очки — чем быстрее, тем больше.","После 10 раундов считается итог."],"tt":"Советы","tips":["Смотри на цвета и лица — по ним ролики узнаются быстрее всего.","Не уверен — подожди пару секунд: картинка станет крупнее, но очков будет меньше.","Лучшая подготовка — посмотреть свежие видео на канале 🙂"]},
"bricks":{"rt":"Как играть","rules":["Веди дощечку пальцем по полю и отбивай мяч вверх. Мяч, упавший мимо дощечки, потерян — всего их 3.","Мяч лежит на дощечке, пока ты не нажмёшь на поле (или пробел); через 2,5 секунды он полетит сам.","Кирпич — 10 очков, крепкий кирпич — 2 удара по 10, ⭐ звёздный — 30 очков и широкая дощечка.","Разбил всю стенку — +100 очков, встаёт новая, мяч летит быстрее.","Партия длится 2 минуты. Если время вышло, а мячи остались, — +50 за каждый мяч."],"tt":"Советы","tips":["Куда попал мяч на дощечке, туда он и полетит: краем — вбок, серединой — почти вверх.","Пробей дыру сбоку стенки — мяч залетит наверх и сам разобьёт много кирпичей.","Береги мячи до конца: каждый оставшийся — ещё 50 очков."]},
"bubbles":{"rt":"Как играть","rules":["Веди пальцем по полю — пушка целится. Отпусти — пузырь полетит.","Три и больше пузыря одного цвета рядом лопаются: 10 очков за каждый.","Пузыри, которые больше ни на чём не держатся, падают: 20 очков за каждый.","Каждые 8 выстрелов сверху добавляется новый ряд. С 40-го выстрела появляется пятый цвет.","Каждый 12-й пузырь — 💥 бомба. Очистил всё поле — +300 и новые ряды.","Пузырь встал за красной линией — конец. Партия длится до 2 минут."],"tt":"Советы","tips":["Целься в опоры: лопнешь пару пузырей сверху — упадёт целая гроздь снизу.","Отскок от стенки помогает попасть за пузыри, которые закрывают цель.","Если текущий пузырь некуда поставить — тапни по пушке и возьми следующий."]},
"cannon":{"rt":"Как играть","rules":["Веди пальцем (или мышью с зажатой кнопкой) — пушка едет за ним и стреляет сама. Клавиатура: ← → или A D.","Попадание — 1 очко и минус 1 к числу на шарике. Число дошло до нуля — шарик лопается (+5) и делится на два поменьше.","Шарик приземлился на пушку — минус ❤, пушка мигает и полторы секунды неуязвима. ❤ кончились — конец.","Большой шарик роняет ⚡: поймай его пушкой — 6 секунд двойного огня.","Новые шарики приходят всё чаще и всё крепче. Партия длится 2 минуты."],"tt":"Советы","tips":["Стреляй по шарику, пока он высоко, а когда он падает — отъезжай в сторону.","Маленькие шарики прыгают низко — сначала добивай их, пока не набралось много.","⚡ лучше ловить, когда на поле большой шарик: двойной огонь быстро его лопнет."]},
"colorjump":{"rt":"Как играть","rules":["Тап (или пробел) — капля подпрыгивает. Без тапов она падает.","Сквозь полосу можно пройти, только если цвет полосы над каплей совпадает с цветом капли.","Клякса краски перекрашивает каплю. Радужная клякса пропускает через следующую полосу любого цвета.","Полоса — 1 очко, полоса после радуги — 2 очка.","Не тот цвет или капля упала за нижний край — конец. Через 2 минуты — финиш."],"tt":"Советы","tips":["Не спеши: подпрыгивай под полосой и жди, пока над каплей поедет нужный цвет.","Через полосу нужно два-три быстрых тапа подряд — начинай, когда нужный цвет только подъезжает.","Смотри, в какую сторону едет полоса, а не только какой цвет сейчас над каплей."]},
"cuberun":{"rt":"Как играть","rules":["Первый тап — старт и прыжок. Каждый следующий тап — прыжок.","Перепрыгивай кактусы. Задел кактус или врезался в бок ящика — забег окончен.","На ящик можно запрыгнуть сверху и бежать по нему.","Каждое пройденное препятствие — 1 очко, ⭐ звезда — 2 очка.","Через 2 минуты — финиш."],"tt":"Советы","tips":["Прыгай чуть раньше перед длинной группой кактусов — кубик пролетит над ней по центру.","На высокие ящики прыгай заранее: кубику нужна высота.","Скорость растёт с каждым препятствием — смотри вперёд, а не на кубик."]},
"darts":{"rt":"Как играть","rules":["Первый тап запускает игру.","Тап (или пробел) — бросок дротика. Воткнулся — 1 очко.","Задел уже воткнутый дротик — промах, игра окончена.","Все дротики из запаса (внизу) в мишени — +5 очков и следующая мишень.","⭐ Золотой сектор — +2 очка. На всё — 2 минуты, мишеней — 15."],"tt":"Советы","tips":["Бросай, когда под мишенью свободное место, а не сразу после прошлого дротика.","Смотри на тёмную метку в центре: она показывает, куда и как быстро крутится мишень.","Мишень, которая крутится туда-обратно, на миг замирает при развороте — лучший момент для броска."]},
"descent":{"rt":"Как играть","rules":["Первый тап запускает игру. Огонёк падает и отскакивает от камня.","Тяни пальцем или мышью влево / вправо — кольца крутятся. Клавиши ← / → или A / D.","Щель под огоньком — он ныряет ниже, +1 очко. ⭐ Золотая плита — отскок, +3.","Огонёк упал на 🔥 лаву — игра окончена.","До дна 60 колец, на всё 2 минуты. На дне за каждую оставшуюся секунду +1."],"tt":"Советы","tips":["Крути заранее, пока огонёк летит вверх после отскока.","Большая щель из трёх плит — самая безопасная.","Золото даёт +3, но отскок отнимает время — решай, что важнее."]},
"drone":{"rt":"Как играть","rules":["Тап (или пробел) — дрон подлетает вверх. Без тапов он падает.","Пролетай сквозь щели в воротах. Задел ворота или землю — конец.","Ворота — 1 очко, точно через кольцо в центре — ещё 1 очко.","Батарейка тает каждую секунду. Молния ⚡ в центре каждых пятых ворот добавляет 4 секунды.","Батарейка села — полёт окончен. Потолок не опасен."],"tt":"Советы","tips":["Тапай короткими сериями, когда дрон опускается ниже кольца, — так он держится посередине.","Следующие ворота видно заранее: начинай подниматься или опускаться сразу после пролёта.","Не пропускай молнии: без них батарейки хватит меньше чем на минуту."]},
"evolve":{"rt":"Как играть","rules":["Нажми на одного, потом на второго такого же — они сольются в следующего по цепочке во второй клетке.","Птенец — +1, ящерка — +3, дракончик — +8, дракон — +25. Дракон улетает и освобождает клетку.","Слияние меньше чем через секунду после прошлого — серия: сверху +1, +2… до +5.","Выбранного можно переставить в пустую клетку.","Гнездо переполнилось (новому яйцу некуда упасть) — игра окончена. Иначе через 2 минуты. Два дракона и больше — победа."],"tt":"Советы","tips":["Сливай яйца сразу — их больше всего, и они быстро забивают гнездо.","Держи одинаковых рядом: так быстрее найти пару.","Серия растёт, если сливать без пауз, — не отвлекайся."]},
"fifteen":{"rt":"Как играть","rules":["Нажми плитку рядом с пустой клеткой — она переедет в пустую клетку.","Если нажать плитку в той же строке или столбце, что и пустая клетка, сдвинется вся линия до неё — это один ход.","Собери плитки по порядку слева направо и сверху вниз, пустая клетка — в правом нижнем углу.","Собранная доска — 100 очков. Собрал все три — бонус 2 очка за каждую оставшуюся секунду.","Время вышло — за каждую плитку на своём месте на текущей доске +3 очка."],"tt":"Советы","tips":["Собирай по рядам: сначала верхний ряд, потом следующий — и не трогай уже собранное.","Последние две плитки ряда ставь вместе: сначала одну чуть в сторону, потом обе на место.","Цвет помогает: плитки одного цвета живут в одном ряду."]},
"flip":{"rt":"Как играть","rules":["Зажми палец (кнопку мыши или пробел) — сила качается от слабой до сильной и обратно. Отпусти — бросок.","Бутылка сама летит к табурету, а сила решает, как высоко она взлетит и сколько оборотов успеет сделать (один оборот — 0,8 секунды полёта).","Встала на дно — 10 очков, почти идеально ровно — 15, встала на крышку — 25. Два оборота и больше — очки ×2.","Удачные броски подряд — серия: +2, +4, +6… Упала — серия сначала.","Всего 10 бросков. Не бросаешь 8 секунд — бутылка полетит сама, но слабо."],"tt":"Советы","tips":["К высокому табурету нужно бросать сильнее — но и оборотов будет больше.","Поймай ритм: сила качается туда и обратно всегда одинаково.","Полтора оборота — на крышку: это 25 очков, но попасть сложнее."]},
"gates":{"rt":"Как играть","rules":["Веди фонарик пальцем влево и вправо. Когда ряд ворот доходит до фонарика, срабатывают ворота прямо под ним.","«+» и «×» прибавляют светлячков, «−» и «÷» отнимают (при делении остаток гаснет).","☁️ Туча стоит на всю ширину дороги и гасит столько светлячков, сколько на ней написано.","Если светлячков стало 0 — путь окончен.","Счёт — сколько светлячков ты донёс до большого фонаря в конце пути (24 ряда)."],"tt":"Советы","tips":["«×2» выгоднее «+10», только если светлячков больше десяти. Считай до того, как ряд подъедет.","Смотри вперёд: если скоро туча — лучше набрать светлячков заранее.","Держи палец пониже на экране, чтобы видеть следующие ворота."]},
"hole":{"rt":"Как играть","rules":["Веди дыру пальцем: она плывёт к точке чуть выше пальца, чтобы палец её не закрывал.","Проглотить можно только то, что меньше дыры (такие предметы обведены светлым кругом).","Чем крупнее предмет, тем больше очков: пылинка — 1, планета — 18, звезда — 50.","На месте проглоченного через 2 секунды появляется новый предмет — вдали от дыры.","Партия длится минуту. ☄️ Проглоченная комета добавляет 3 секунды."],"tt":"Советы","tips":["Сначала собирай мелочь рядом — дыра быстро подрастёт.","Кометы летят быстро: перехвати их на пути, а не догоняй.","Большие предметы не таранят — обходи их, пока не подрастёшь."]},
"jumper":{"rt":"Как играть","rules":["Первый тап — первый прыжок. Дальше белка прыгает сама, когда приземляется на ветку.","Веди пальцем или мышью влево-вправо (можно отпускать) — белка бежит туда. Клавиши ← / → или A / D.","Очки — высота в метрах плюс 5 за каждый 🌰 жёлудь.","Сухая ветка (с трещиной) ломается после прыжка. Мимо веток — белка падает, игра окончена.","Подъём длится 2 минуты."],"tt":"Советы","tips":["Веди белку под ветку заранее, пока она летит вверх.","Не гонись за каждым желудем — упасть обиднее.","На качающуюся ветку прыгай, когда она едет навстречу."]},
"lights":{"rt":"Как играть","rules":["Нажатие на окно переключает его и соседние окна сверху, снизу, слева и справа: горящие гаснут, тёмные загораются.","Погаси все окна дома — он уснёт, и откроется следующий.","За дом — 100 очков, +25 за каждое нажатие меньше нормы и −10 за каждое лишнее (не меньше 20). В норму — ⭐.","На всю ночь — 2 минуты. Уложил все 5 домов — бонус 3 очка за каждую оставшуюся секунду.","Время вышло — считаются уже уснувшие дома."],"tt":"Советы","tips":["Два нажатия на одно окно отменяют друг друга — каждое окно нужно нажать не больше одного раза.","Порядок нажатий не важен — важно, какие окна нажаты.","Начни с верхнего ряда: гаси его нажатиями по ряду под ним — и спускайся вниз."]},
"lock":{"rt":"Как играть","rules":["Первый тап запускает стрелку.","Тап (или пробел), когда стрелка над огоньком, — щелчок, 1 очко. После щелчка стрелка бежит в обратную сторону.","Нажал слишком рано или стрелка проехала огонёк — замок сломан, игра окончена.","Щёлкни все штифты (лампочки сверху) — сейф открыт, +5 очков. Золотой огонёк — 3 очка.","Открой все 20 сейфов — победа."],"tt":"Советы","tips":["Смотри на огонёк, а не на стрелку: так проще поймать момент.","Золотой огонёк меньше обычного — жми чуть точнее.","После щелчка стрелка разворачивается — следующий огонёк всегда впереди по её ходу."]},
"parking":{"rt":"Как играть","rules":["Нажми на машину — она поедет по своей стрелке до края стоянки.","Если на пути стоит другая машина, никто не едет: «БИП!», мешающая машина качается, −5 очков (не ниже нуля).","Машина уехала — +10 очков. Стоянка пуста — +30, и открывается следующая.","Освободил все три стоянки — бонус 2 очка за каждую оставшуюся секунду. Время вышло — игра окончена."],"tt":"Советы","tips":["Сначала ищи машины, у которых путь до края уже свободен.","Посмотри, кто мешает большому числу машин, — выпусти его пораньше.","Не жми наугад: каждый «БИП» стоит 5 очков."]},
"pegs":{"rt":"Как играть","rules":["Веди пальцем над гвоздиками — шарик двигается за ним. Отпусти — шарик упадёт.","⭐ Золотая корзинка — 50 очков, зелёная — 20, остальные — 2.","Попадания в золотую или зелёную подряд — серия: +10 за каждое попадание сверх первого.","Не бросишь за 6 секунд — шарик упадёт сам и очков не принесёт.","С 4-го шарика посередине ездит планка — шарик от неё отскакивает.","У тебя 10 шариков."],"tt":"Советы","tips":["Один и тот же бросок всегда приводит в одну и ту же корзинку — запоминай удачные места.","Целься не прямо над корзинкой: шарик почти всегда уходит вбок от первого гвоздика.","Планку лучше переждать: брось, когда она уехала в сторону."]},
"pet":{"rt":"Как играть","rules":["Три шкалы: 🍎 еда, ⚽ игра и 💤 сон. Они понемногу тают, и чем ближе вечер, тем быстрее.","Кнопки «Кормить», «Играть» и «Спать» пополняют свою шкалу. Пока Буся ест, играет или спит, другие кнопки ждут.","Шкала почти полная — Буся скажет «Не хочу!», и ты потеряешь 3 очка.","💭 Появилось желание — исполни его за 4 секунды и получи +15 очков.","Каждая секунда дня — +1 очко, весь день — ещё +30. Любая шкала опустела — Буся обиделся и ушёл гулять, игра окончена."],"tt":"Советы","tips":["Не жди, пока шкала станет красной: помогай, когда она на середине.","Укладывай спать, когда еда и игра полные — во сне они тают медленнее.","Желание стоит 15 секунд жизни — лови каждое."]},
"planets":{"rt":"Как играть","rules":["Веди пальцем по полю — тело над космосом двигается за ним. Отпусти — тело упадёт.","Два одинаковых тела сливаются в следующее по цепочке. Чем больше новое тело, тем больше очков: 2, 4, 8 … 256.","Две звезды — 💥 сверхновая: +500 очков, обе исчезают.","☄️ Комета разбивает первое тело, которое задела (+очки этого тела).","Не бросишь 2,5 секунды — тело упадёт само.","Тело выше красной линии дольше 2 секунд — космос переполнен, конец. Партия длится до 2 минут."],"tt":"Советы","tips":["Крупные тела держи по краям и внизу, мелкие — сверху: так им проще встретиться с парой.","Смотри в строку над полем: там следующее тело — планируй бросок заранее.","Комету бросай на тело, которое мешает слиянию."]},
"popit":{"rt":"Как играть","rules":["Нажми на целую пупырку — она лопнет, +1 очко.","Лопнул все 30 — +10 очков, лист переворачивается, и пупырки снова целые.","✨ Золотая пупырка появляется ненадолго — успей нажать, это +5 очков.","У тебя 40 секунд. Время вышло — игра окончена."],"tt":"Советы","tips":["Лопай по рядам — так не пропустишь пупырку в конце листа.","Играй двумя пальцами: каждый палец — свою половину листа.","Золотую лови сразу — за полторы секунды она исчезнет."]},
"pour":{"rt":"Как играть","rules":["Рисуй пальцем (или мышью с зажатой кнопкой) линии. Отпустил палец — из крана польётся вода.","Пока рисуешь, вода ждёт. Не рисуешь 4 секунды — польётся сама. Пробел — лить сразу.","Каждая капля в стакане — 1 очко. 80 капель из 100 — ⭐ и +20 очков.","Налил больше половины — бонус за оставшиеся чернила: 1 очко за каждые 20 единиц.","Пока вода льётся, можно дорисовывать линии, если остались чернила.","Партия длится 2 минуты, уровни идут один за другим."],"tt":"Советы","tips":["Заканчивай горку у середины стакана, чуть ниже края, — быстрые капли не перелетят.","Не делай резких изломов: на крутом повороте капли слетают с линии.","Если полка мешает — проведи горку под ней, а струя пусть пролетит мимо края полки."]},
"repeat":{"rt":"Как играть","rules":["Слушай и смотри: клавиши загораются по одной — это мелодия раунда.","Когда покажется «Твой ход», нажми те же клавиши в том же порядке.","Каждая новая верная нота — +1 очко, вся мелодия раунда — ещё +5. Следующий раунд на ноту длиннее.","Ошибка или 6 секунд без нажатия — минус сердечко, мелодия прозвучит ещё раз.","Три сердечка потеряно — игра окончена. Всего 40 раундов."],"tt":"Советы","tips":["Мелодия каждого раунда — это прошлая плюс одна новая нота в конце. Запоминай только новую.","Пой ноты про себя или запоминай знаки: ●▲■★.","Нажатия во время показа не считаются — не торопись."]},
"riddles":{"rt":"Как играть","rules":["Прочитай загадку и выбери один из четырёх ответов.","На ответ — 15 секунд. Верно — 50 очков и ещё 4 за каждую оставшуюся секунду. Неверно или время вышло — 0.","После ответа появится объяснение. Нажми «Дальше ▶» или подожди 2,5 секунды.","Всего 10 загадок. 7 и больше верных ответов — победа."],"tt":"Советы","tips":["Читай вопрос до конца: подвох обычно в одном слове.","Самый «очевидный» ответ часто неверный.","Если сомневаешься, подумай, не про буквы ли загадка."]},
"road":{"rt":"Как играть","rules":["Первый тап запускает игру.","Тап (или ↑, W, пробел) — шаг вперёд. Свайп влево / вправо (← →) — шаг вбок, свайп вниз (↓) — шаг назад, не дальше 3 рядов от лучшего.","Машина задела ёжика — игра окончена. Сквозь кусты пройти нельзя.","Очки — самый дальний ряд плюс 3 за каждый 🍄 гриб.","Через 2 минуты прогулка заканчивается."],"tt":"Советы","tips":["Не торопись: стоять на лужайке безопасно, а машины ездят по кругу с постоянной скоростью.","Шагай сразу за проехавшей машиной — так больше времени до следующей.","Шаг вбок на дороге спасает, если машина уже близко, а впереди тоже едет."]},
"shield":{"rt":"Как играть","rules":["Рисуй пальцем (или мышью с зажатой кнопкой) стенки на пути спам-ботов. На самом экране стрима рисовать нельзя.","Бот, который упёрся в стенку почти на секунду, отписывается и улетает — +5 очков.","Голубая полоска внизу — чернила: каждая стенка их тратит, а со временем они пополняются.","Бот, долетевший до экрана, снимает одно ❤. У стрима 3 ❤ — когда они кончатся, эфир окончен.","За каждую секунду эфира — 2 очка. Продержался 90 секунд — ещё +50 за каждое оставшееся ❤."],"tt":"Советы","tips":["Рисуй короткие стенки поперёк пути бота — так чернил хватит надолго.","Боты с одной стороны часто летят рядом: одна дуга может остановить сразу нескольких.","Не рисуй вплотную к экрану — дай стенке время задержать бота."]},
"slice":{"rt":"Как играть","rules":["Режь овощи быстрым взмахом пальца (или мышью с зажатой кнопкой). Просто нажатие не режет.","Овощ — 1 очко, овощ из заказа супа — 2 очка. Собрал весь заказ — +10 и новый заказ.","Три и больше овощей одним взмахом — дополнительные очки за каждый сверх двух.","Упал неразрезанный овощ или разрезан 🪨 камень — минус ❤. Их всего 3.","Партия длится до 2 минут."],"tt":"Советы","tips":["Режь овощи на взлёте — у них уже есть время подлететь и собраться в кучку.","Смотри на заказ: те овощи, что в заказе, стоят вдвое больше.","Если рядом с овощем камень — подожди, пока они разлетятся."]},
"sling":{"rt":"Как играть","rules":["Коснись поля в любом месте, потяни палец назад и отпусти — камешек полетит в обратную сторону. Чем дальше тянешь, тем сильнее.","Банка — 10 очков, ⭐ золотая — 30. Третья и следующие банки за один выстрел — ещё +5 за каждую.","Сбил все банки — +50, ещё 2 камешка (не больше 6) и новый тир.","Камешки кончились — конец. Партия длится до 2 минут.","Клавиатура: ← → угол, ↑ ↓ сила, пробел — выстрел."],"tt":"Советы","tips":["Цель в нижнюю банку столбика: верхние упадут сами.","Пологий сильный выстрел сбивает банки в ряд, навесной — достаёт банки за высокими ящиками.","Точки прицела показывают только начало пути — дальше камешек опускается сильнее."]},
"spinner":{"rt":"Как играть","rules":["Веди пальцем (или мышью) по кругу — спиннер раскручивается: четверть круга прибавляет около 1,5 оборота в секунду.","Прижми палец и держи на месте — спиннер тормозит. Сам он тоже понемногу замедляется.","Каждые 0,1 секунды со скоростью в зелёной зоне — +1 очко. В зоне дольше 2 секунд — 🔥 и +2.","Зона меняется каждые 5 секунд. Игра длится 40 секунд.","Клавиатура: пробел или → — толчок, ↓ — тормоз."],"tt":"Советы","tips":["Короткие свайпы точнее одного длинного.","Скорость падает сама — подталкивай заранее, пока стрелка у нижнего края зоны.","Зона сдвинулась ниже — коснись спиннера и подержи палец."]},
"tiles":{"rt":"Как играть","rules":["В каждом ряду одна чёрная плитка. Жми чёрные плитки по порядку — снизу вверх.","Поле начинает ехать после нажатия на плитку «СТАРТ» и с каждой плиткой едет быстрее.","Нажал на белую клетку в текущем ряду или выше — игра окончена.","Чёрная плитка ушла за нижний край — тоже конец.","Обычная плитка — 1 очко, ⭐ золотая — 3 очка."],"tt":"Советы","tips":["Смотри на ряд выше того, который нажимаешь, — так рука успевает заранее.","Не торопись тапать по верхним плиткам: засчитывается только следующая по порядку.","На компьютере удобнее играть двумя руками: D и F — левая, J и K — правая."]},
"tower":{"rt":"Как играть","rules":["Над башней ездит блок. Тап (или пробел) — блок падает на башню.","Часть блока, которая свисает за край, отрезается — башня становится уже.","Каждый этаж — 1 очко. Ровно в край (почти без свеса) — ⭐ 2 очка, ширина не меняется.","Если не нажать, кран опустит блок сам — там, где он окажется.","Блок не попал на башню — конец. Крыша на 100-м этаже — победа."],"tt":"Советы","tips":["Нажимай чуть раньше, чем блок встанет точно над башней: он едет быстро.","Ровные укладки подряд сохраняют ширину — так проще дойти до крыши.","Выше 50-го этажа блок ездит очень быстро — смотри на край башни, а не на блок."]},
"twolanes":{"rt":"Как играть","rules":["Первый тап запускает игру.","Тап по левой половине поля (или ←, F) перестраивает левую машинку, по правой (→, J) — правую.","🔋 Батарейка — +1 очко и подзарядка, ⭐ звезда — +3.","Барьер — авария, игра окончена. Заряд кончился (полоска внизу) — тоже конец.","Доедешь до конца двухминутной трассы — финиш."],"tt":"Советы","tips":["Смотри на ближайший предмет у каждой машинки — следующий всегда успеешь.","Держи большие пальцы над обеими половинами экрана.","Полоска заряда покраснела — лови ближайшую батарейку."]},
"watersort":{"rt":"Как играть","rules":["Нажми банку, потом ту, куда перелить. Переливается верхний цвет — столько слоёв, сколько влезет.","Лить можно только на такой же цвет или в пустую банку. В банке помещается 4 слоя.","Краска впервые собрана в одну банку — +10 очков, банка закрывается крышкой ⭐.","Все краски разложены — уровень пройден, +50 очков. Прошёл все три — бонус 2 очка за каждую оставшуюся секунду.","«↶ Отменить ход» возвращает последнее переливание. Время вышло — игра окончена."],"tt":"Советы","tips":["Не занимай обе пустые банки сразу — они нужны, чтобы распутать краски.","Сначала освобождай банку, где нужного цвета больше всего сверху.","Застрял — отмени пару ходов: это бесплатно."]},
"zigzag":{"rt":"Как играть","rules":["Первый тап — старт. Шарик катится вверх и вправо.","Каждый тап (или пробел) — поворот в другую сторону.","Каждый пройденный угол — 1 очко. Поворот у самого огонька угла — ещё 1 очко.","Шарик съехал с дороги — игра окончена.","Через 2 минуты — финиш."],"tt":"Советы","tips":["Поворачивай, когда шарик доезжает до огонька, — не раньше.","Если шарик едет у края дороги, поверни чуть раньше или позже, чтобы вернуться на середину.","Смотри на следующий угол, а не на шарик: так рука успевает заранее."]}};
